import type {
  CellProps,
  CellAvatarProps,
  CellAssetIconProps,
  CellInfoBlockProps,
  CellBadgeProps,
  CellInlineBadgeProps,
  CellButtonProps,
  CellChipProps,
  CellExpandToggleProps,
  CellSubRowIndicatorProps,
  CellIconButtonProps,
  CellLinkProps,
  CellNumberProps,
  CellSvgIconProps,
} from "./cell.types";
import type { PolymorphicRef } from "@types";

import React, { cloneElement, forwardRef } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";
import { Avatar } from "@components/avatar";
import { AssetIcon } from "@components/asset-icon";
import { Badge } from "@components/badge";
import { InlineBadge } from "@components/inline-badge";
import { Button } from "@components/button";
import { Chip } from "@components/chip";
import { IconButton } from "@components/icon-button";
import { InfoBlock } from "@components/info-block";
import { SvgIcon } from "@components/svg-icon";
import { ArrowLineDownCurveRight, ChevronRight, ChevronDown } from "@exp-textura/icons";

import { CellClasses, StyledCell } from "./cell.styles";

const CellRoot = forwardRef<HTMLDivElement, CellProps>(
  ({ className, variant = "default", ...props }, ref) => {
    const theme = useTheme();
    return (
      <StyledCell
        ref={ref}
        className={clsx(CellClasses.root, className)}
        currentTheme={theme}
        variant={variant}
        {...props}
      />
    );
  },
);
CellRoot.displayName = "Cell";

const AssetIconCell = ({ children, className, style, ...props }: CellAssetIconProps) => {
  const theme = useTheme();
  return (
    <StyledCell className={clsx(CellClasses.root, className)} currentTheme={theme} style={style}>
      <AssetIcon className={CellClasses.assetIcon} size="md" {...props}>
        {children}
      </AssetIcon>
    </StyledCell>
  );
};
AssetIconCell.displayName = "Cell.AssetIcon";

const AvatarCell = ({ children, className, style, ...props }: CellAvatarProps) => {
  const theme = useTheme();
  return (
    <StyledCell className={clsx(CellClasses.root, className)} currentTheme={theme} style={style}>
      <Avatar className={CellClasses.avatar} size="sm" {...props}>
        {children}
      </Avatar>
    </StyledCell>
  );
};
AvatarCell.displayName = "Cell.Avatar";

/** @deprecated Use Cell.InlineBadge instead */
const BadgeCell = ({ children, className, style, ...props }: CellBadgeProps) => {
  const theme = useTheme();
  return (
    <StyledCell className={clsx(CellClasses.root, className)} currentTheme={theme} style={style}>
      <Badge className={CellClasses.badge} type="roomy" {...props}>
        {children}
      </Badge>
    </StyledCell>
  );
};
BadgeCell.displayName = "Cell.Badge";

const InlineBadgeCell = ({ children, className, style, ...props }: CellInlineBadgeProps) => {
  const theme = useTheme();
  return (
    <StyledCell className={clsx(CellClasses.root, className)} currentTheme={theme} style={style}>
      <InlineBadge className={CellClasses.inlineBadge} {...props}>
        {children}
      </InlineBadge>
    </StyledCell>
  );
};
InlineBadgeCell.displayName = "Cell.InlineBadge";

const ButtonCell = ({ children, className, style, ...props }: CellButtonProps) => {
  const theme = useTheme();
  return (
    <StyledCell className={clsx(CellClasses.root, className)} currentTheme={theme} style={style}>
      <Button buttonType="secondary" className={CellClasses.button} size="sm" {...props}>
        {children}
      </Button>
    </StyledCell>
  );
};
ButtonCell.displayName = "Cell.Button";

const ChipCell = ({ children, className, style, ...props }: CellChipProps) => {
  const theme = useTheme();
  return (
    <StyledCell className={clsx(CellClasses.root, className)} currentTheme={theme} style={style}>
      <Chip className={CellClasses.chip} {...props}>
        {children}
      </Chip>
    </StyledCell>
  );
};
ChipCell.displayName = "Cell.Chip";

const IconButtonCell = ({ children, className, style, ...props }: CellIconButtonProps) => {
  const theme = useTheme();
  return (
    <StyledCell className={clsx(CellClasses.root, className)} currentTheme={theme} style={style}>
      <IconButton buttonType="secondary" className={CellClasses.iconButton} size="sm" {...props}>
        {children}
      </IconButton>
    </StyledCell>
  );
};
IconButtonCell.displayName = "Cell.IconButton";

const InfoBlockCell = ({ children, className, style, ...props }: CellInfoBlockProps) => {
  const theme = useTheme();
  const newChildren = React.Children.map(children, (child) => {
    if (
      React.isValidElement(child) &&
      (child.type as { displayName?: string }).displayName === "InfoBlock.Visual"
    ) {
      const visualChildren = React.Children.map(
        (child as React.ReactElement).props.children,
        (visualChild) => {
          if (
            React.isValidElement(visualChild) &&
            (visualChild.type as { displayName?: string }).displayName === "AssetIcon"
          ) {
            return cloneElement(visualChild as React.ReactElement, {
              size: (visualChild as React.ReactElement).props.size || "md",
            });
          } else if (
            React.isValidElement(visualChild) &&
            (visualChild.type as { displayName?: string }).displayName === "Avatar"
          ) {
            return cloneElement(visualChild as React.ReactElement, {
              size: (visualChild as React.ReactElement).props.size || "sm",
            });
          }
          return visualChild;
        },
      );
      return cloneElement(child as React.ReactElement, { children: visualChildren });
    }
    return child;
  });

  return (
    <StyledCell className={clsx(CellClasses.root, className)} currentTheme={theme} style={style}>
      <InfoBlock className={CellClasses.infoBlock} {...props}>
        {newChildren}
      </InfoBlock>
    </StyledCell>
  );
};
InfoBlockCell.displayName = "Cell.InfoBlock";

const Link = forwardRef(
  <C extends React.ElementType = "a">(
    { children, className, style, as, ...props }: CellLinkProps<C>,
    ref: React.ForwardedRef<PolymorphicRef>,
  ) => {
    const theme = useTheme();
    const Component = as || "a";
    return (
      <StyledCell className={clsx(CellClasses.root, className)} currentTheme={theme} style={style}>
        <Component ref={ref} className={CellClasses.link} {...props}>
          {children}
        </Component>
      </StyledCell>
    );
  },
);
Link.displayName = "Cell.Link";

const Number = ({ children, className, style, ...props }: CellNumberProps) => {
  const theme = useTheme();
  return (
    <StyledCell className={clsx(CellClasses.root, className)} currentTheme={theme} style={style}>
      <div className={CellClasses.number} {...props}>
        {children}
      </div>
    </StyledCell>
  );
};
Number.displayName = "Cell.Number";

const SvgIconCell = ({ children, className, style, ...props }: CellSvgIconProps) => {
  const theme = useTheme();
  return (
    <StyledCell className={clsx(CellClasses.root, className)} currentTheme={theme} style={style}>
      <SvgIcon className={CellClasses.svgIcon} fontSize={theme.toRem(24)} {...props}>
        {children}
      </SvgIcon>
    </StyledCell>
  );
};
SvgIconCell.displayName = "Cell.SvgIcon";

const SubRowIndicatorCell = ({
  children,
  className,
  style,
  icon = <ArrowLineDownCurveRight />,
}: CellSubRowIndicatorProps) => {
  const theme = useTheme();
  return (
    <StyledCell className={clsx(CellClasses.root, className)} currentTheme={theme} style={style}>
      <span className={CellClasses.subRowIndicator}>
        <span aria-hidden="true">{icon}</span>
        {children}
      </span>
    </StyledCell>
  );
};
SubRowIndicatorCell.displayName = "Cell.SubRowIndicator";

const ExpandToggleCell = ({
  isExpanded,
  canExpand,
  onToggle,
  children,
  className,
  style,
  collapsedIcon = <ChevronRight />,
  expandedIcon = <ChevronDown />,
  expandAriaLabel = "Expand row",
  collapseAriaLabel = "Collapse row",
}: CellExpandToggleProps) => {
  const theme = useTheme();
  if (!canExpand) {
    return (
      <StyledCell className={clsx(CellClasses.root, className)} currentTheme={theme} style={style}>
        <span className={CellClasses.expandToggle}>{children}</span>
      </StyledCell>
    );
  }
  return (
    <StyledCell className={clsx(CellClasses.root, className)} currentTheme={theme} style={style}>
      <span className={CellClasses.expandToggle}>
        <button
          aria-expanded={isExpanded}
          aria-label={isExpanded ? collapseAriaLabel : expandAriaLabel}
          tabIndex={-1}
          type="button"
          onClick={(e) => {
            e.stopPropagation();
            onToggle();
          }}
        >
          {isExpanded ? expandedIcon : collapsedIcon}
        </button>
        {children}
      </span>
    </StyledCell>
  );
};
ExpandToggleCell.displayName = "Cell.ExpandToggle";

const Cell = Object.assign(CellRoot, {
  AssetIcon: AssetIconCell,
  Avatar: AvatarCell,
  Badge: BadgeCell,
  InlineBadge: InlineBadgeCell,
  Button: ButtonCell,
  Chip: ChipCell,
  IconButton: IconButtonCell,
  InfoBlock: InfoBlockCell,
  Link,
  Number,
  SvgIcon: SvgIconCell,
  ExpandToggle: ExpandToggleCell,
  SubRowIndicator: SubRowIndicatorCell,
});

export default Cell;
